// analyzer/operations.ts:108
pub fn validate_binary_operation(
    evaluator: &TypeEvaluator,
    operator: OperatorType,
    left_type_result: P<TypeResult>,
    right_type_result: P<TypeResult>,
    error_node: ExpressionNode,
    inference_context: Option<P<InferenceContext>>,
    diag: P<DiagnosticAddendum>,
    options: &BinaryOperationOptions,
) -> P<TypeResult> {
    let left_type = left_type_result.type_.get();
    let right_type = right_type_result.type_.get();
    let is_incomplete = left_type_result.is_incomplete.get().unwrap_or(false)
        || right_type_result.is_incomplete.get().unwrap_or(false);
    let mut type_: Option<P<Type>> = None;
    let mut concrete_left_type =
        evaluator.make_top_level_type_vars_concrete(left_type, false, None);
    let mut deprecated_info: Option<MagicMethodDeprecationInfo> = None;

    if BOOLEAN_OPERATOR_MAP.with(|map| map.contains_key(&operator)) {
        // If it's an AND or OR, we need to handle short-circuiting by
        // eliminating any known-truthy or known-falsy types.
        if operator == OperatorType::And {
            // If the LHS evaluates to falsy, the And expression will
            // always return the type of the left-hand side.
            if !evaluator.can_be_truthy(concrete_left_type, 0) {
                return P::new_eval(TypeResult::new(left_type));
            }

            // If the LHS evaluates to truthy, the And expression will
            // always return the type of the right-hand side.
            if !evaluator.can_be_falsy(concrete_left_type, 0) {
                return P::new_eval(TypeResult::new(right_type));
            }

            concrete_left_type = evaluator.remove_truthiness_from_type(concrete_left_type);

            if is_never(right_type) {
                return P::new_eval(TypeResult::new(concrete_left_type));
            }
        } else if operator == OperatorType::Or {
            // If the LHS evaluates to truthy, the Or expression will
            // always return the type of the left-hand side.
            if !evaluator.can_be_falsy(concrete_left_type, 0) {
                return P::new_eval(TypeResult::new(left_type));
            }

            // If the LHS evaluates to falsy, the Or expression will
            // always return the type of the right-hand side.
            if !evaluator.can_be_truthy(concrete_left_type, 0) {
                return P::new_eval(TypeResult::new(right_type));
            }

            concrete_left_type = evaluator.remove_falsiness_from_type(concrete_left_type);

            if is_never(right_type) {
                return P::new_eval(TypeResult::new(concrete_left_type));
            }
        }

        if is_never(left_type) || is_never(right_type) {
            return P::new_eval(TypeResult::new(NeverType::create_never().0));
        }

        // The "in" and "not in" operators make use of the __contains__
        // magic method.
        if operator == OperatorType::In || operator == OperatorType::NotIn {
            let result = validate_containment_operation(
                evaluator,
                operator,
                left_type_result,
                concrete_left_type,
                right_type_result,
                error_node,
                diag,
            );

            let info = result.cold().magic_method_deprecation_info.clone();
            if let Some(info) = &info {
                deprecated_info = Some(info.clone());
            }

            let result_type = result.type_.get();
            type_ = Some(result_type);

            // Assume that a bool is returned even if the type is unknown.
            if !is_never(result_type) {
                type_ = Some(evaluator.get_built_in_object(error_node, "bool", None));
            }
        } else {
            type_ = Some(evaluator.map_subtypes_expand_type_vars(
                concrete_left_type,
                /* options */ None,
                &mut |left_subtype_expanded, left_subtype_unexpanded, _| {
                    Some(evaluator.map_subtypes_expand_type_vars(
                        right_type,
                        Some(&MapSubtypesOptions {
                            condition_filter: get_type_condition(left_subtype_expanded),
                            ..Default::default()
                        }),
                        &mut |_, right_subtype_unexpanded, _| {
                            // If the operator is an AND or OR, we need to combine the two types.
                            if operator == OperatorType::And || operator == OperatorType::Or {
                                return Some(combine_types(
                                    &[left_subtype_unexpanded, right_subtype_unexpanded],
                                    None,
                                ));
                            }
                            // The other boolean operators always return a bool value.
                            Some(evaluator.get_built_in_object(error_node, "bool", None))
                        },
                        0,
                    ))
                },
                0,
            ));
        }
    } else if BINARY_OPERATOR_MAP.with(|map| map.contains_key(&operator)) {
        if is_never(left_type) || is_never(right_type) {
            return P::new_eval(TypeResult::new(NeverType::create_never().0));
        }

        // Handle certain operations on certain homogenous literal types
        // using special-case math. For example, Literal[1, 2] + Literal[3, 4]
        // should result in Literal[4, 5, 6].
        if options.is_literal_math_allowed.unwrap_or(false) {
            type_ = calc_literal_for_binary_op(operator, left_type, right_type);
        }

        if type_.is_none() {
            let result = validate_arithmetic_operation(
                evaluator,
                operator,
                left_type_result,
                right_type_result,
                error_node,
                inference_context,
                diag,
                options,
            );

            let info = result.cold().magic_method_deprecation_info.clone();
            if let Some(info) = &info {
                deprecated_info = Some(info.clone());
            }

            type_ = Some(result.type_.get());
        }
    }

    P::new_eval(TypeResult {
        cold: TypeResultCold {
            magic_method_deprecation_info: deprecated_info,
            ..Default::default()
        }
        .into_cold(),
        ..TypeResult::new(type_.unwrap_or_else(|| UnknownType::create(is_incomplete).0))
    })
}

// analyzer/operations.ts:248
pub fn get_type_of_binary_operation(
    evaluator: &TypeEvaluator,
    node: BinaryOperationNode,
    flags: EvalFlags,
    inference_context: Option<P<InferenceContext>>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<TypeResult> {
    let left_expression = node.d().left_expr.get();
    let mut right_expression = node.d().right_expr.get();
    let operator = node.d().operator.get();
    let mut is_incomplete = false;
    let mut type_errors = false;

    // If this is a comparison and the left expression is also a comparison,
    // we need to change the behavior to accommodate python's "chained
    // comparisons" feature.
    if operator_supports_chaining(operator) {
        if let Some(right_binary) = BinaryOperationNode::cast(right_expression) {
            if !right_binary.d().has_parens.get()
                && operator_supports_chaining(right_binary.d().operator.get())
            {
                // Evaluate the right expression so it is type checked.
                get_type_of_binary_operation(
                    evaluator,
                    right_binary,
                    flags,
                    inference_context,
                    node_info,
                );

                // Use the left side of the right expression for comparison purposes.
                right_expression = right_binary.d().left_expr.get();
            }
        }
    }

    // For most binary operations, the "expected type" is applied to the output
    // of the magic method for that operation. However, the "or" and "and" operators
    // have no magic method, so we apply the expected type directly to both operands.
    let mut expected_operand_type = if operator == OperatorType::Or || operator == OperatorType::And
    {
        inference_context.map(|inference_context| inference_context.expected_type.get())
    } else {
        None
    };

    // Handle the very special case where the expected type is a list
    // and the operator is a multiply. This comes up in the common case
    // of "x: List[Optional[X]] = [None] * y" where y is an integer literal.
    let mut expected_left_operand_type: Option<P<Type>> = None;
    if operator == OperatorType::Multiply {
        if let Some(inference_context) = inference_context {
            let expected_type = inference_context.expected_type.get();
            if is_class_instance(expected_type)
                && ClassType::is_built_in(ClassType(expected_type), Some(&["list".to_string()]))
                && ClassType(expected_type)
                    .d()
                    .priv_
                    .borrow()
                    .type_args
                    .as_ref()
                    .is_some_and(|type_args| !type_args.is_empty())
                && node.d().left_expr.get().node_type == ParseNodeType::List
            {
                expected_left_operand_type = Some(expected_type);
            }
        }
    }

    let effective_expected_type = expected_operand_type.or(expected_left_operand_type);
    let left_type_result = evaluator.get_type_of_expression(
        left_expression,
        flags,
        make_inference_context(effective_expected_type, None, None),
    );
    let mut left_type = left_type_result.type_.get();

    if expected_operand_type.is_none() {
        if operator == OperatorType::Or || operator == OperatorType::And {
            // For "or" and "and", use the type of the left operand under certain
            // circumstances. This allows us to infer a better type for expressions
            // like `x or []`. Do this only if it's a generic class (like list or dict)
            // or a TypedDict.
            if some_subtypes(left_type, &mut |subtype| {
                if !is_class_instance(subtype) {
                    return false;
                }

                ClassType::is_typed_dict_class(ClassType(subtype))
                    || !ClassType(subtype)
                        .d()
                        .shared
                        .get()
                        .type_params
                        .borrow()
                        .is_empty()
            }) {
                expected_operand_type = Some(left_type);
            }
        } else if operator == OperatorType::Add
            && node.d().right_expr.get().node_type == ParseNodeType::List
        {
            // For the "+" operator , use this technique only if the right operand is
            // a list expression. This heuristic handles the common case of `my_list + [0]`.
            expected_operand_type = Some(left_type);
        } else if operator == OperatorType::BitwiseOr {
            // If this is a bitwise or ("|"), use the type of the left operand. This allows
            // us to support the case where a TypedDict is being updated with a dict expression.
            if is_class_instance(left_type) && ClassType::is_typed_dict_class(ClassType(left_type))
            {
                expected_operand_type = Some(left_type);
            }
        }
    }

    let right_type_result = evaluator.get_type_of_expression(
        right_expression,
        flags,
        make_inference_context(expected_operand_type, None, None),
    );
    let mut right_type = right_type_result.type_.get();

    if left_type_result.is_incomplete.get().unwrap_or(false)
        || right_type_result.is_incomplete.get().unwrap_or(false)
    {
        is_incomplete = true;
    }

    // Is this a "|" operator used in a context where it is supposed to be
    // interpreted as a union operator?
    if operator == OperatorType::BitwiseOr
        && !custom_metaclass_supports_method(left_type, "__or__")
        && !custom_metaclass_supports_method(right_type, "__ror__")
    {
        let mut adjusted_right_type = right_type;
        let mut adjusted_left_type = left_type;
        if !is_none_instance(left_type) && is_none_instance(right_type) {
            // Handle the special case where "None" is being added to the union
            // with something else. Even though "None" will normally be interpreted
            // as the None singleton object in contexts where a type annotation isn't
            // assumed, we'll allow it here.
            adjusted_right_type = convert_to_instantiable(evaluator.get_none_type(), true);
        } else if !is_none_instance(right_type) && is_none_instance(left_type) {
            adjusted_left_type = convert_to_instantiable(evaluator.get_none_type(), true);
        }

        if is_unionable_type(&[adjusted_left_type, adjusted_right_type]) {
            if is_instantiable_class(adjusted_left_type) {
                adjusted_left_type =
                    specialize_with_default_type_args(ClassType(adjusted_left_type)).0;
            }

            if is_instantiable_class(adjusted_right_type) {
                adjusted_right_type =
                    specialize_with_default_type_args(ClassType(adjusted_right_type)).0;
            }

            return create_union_type(
                evaluator,
                node,
                flags,
                left_type_result,
                right_type_result,
                adjusted_right_type,
                adjusted_left_type,
                node_info,
            );
        }
    }

    if flags.any(EvalFlags::TypeExpression) {
        // Exempt "|" because it might be a union operation involving unknowns.
        if operator != OperatorType::BitwiseOr {
            evaluator.add_diagnostic(
                DiagnosticRule::reportInvalidTypeForm,
                &LocMessage::binary_operation_not_allowed(),
                node.0,
                None,
            );
            return P::new_eval(TypeResult::new(UnknownType::create(false).0));
        }
    }

    // Optional checks apply to all operations except for boolean operations.
    let mut is_left_optional_type = false;
    if !BOOLEAN_OPERATOR_MAP.with(|map| map.contains_key(&operator)) {
        // None is a valid operand for == and != even if the type stub says otherwise.
        if operator == OperatorType::Equals || operator == OperatorType::NotEquals {
            left_type = remove_none_from_union(left_type);
        } else {
            is_left_optional_type = is_optional_type(left_type);
        }

        // None is a valid operand for == and != even if the type stub says otherwise.
        if operator == OperatorType::Equals || operator == OperatorType::NotEquals {
            right_type = remove_none_from_union(right_type);
        }
    }

    let diag = DiagnosticAddendum::new();

    // Don't use literal math if the operation is within a loop
    // because the literal values may change each time. We also don't want to
    // apply literal math within the body of a lambda because they are often
    // used as callbacks where the value changes each time they are called.
    let is_literal_math_allowed = !is_within_loop(node.0) && get_enclosing_lambda(node.0).is_none();

    // Don't special-case tuple __add__ if the left type is a union. This
    // can result in an infinite loop if we keep creating new tuple types
    // within a loop construct using __add__.
    let is_tuple_add_allowed = !is_union(left_type);

    let type_result = validate_binary_operation(
        evaluator,
        operator,
        P::new_eval(TypeResult {
            is_incomplete: Cell::new(left_type_result.is_incomplete.get()),
            ..TypeResult::new(left_type)
        }),
        P::new_eval(TypeResult {
            is_incomplete: Cell::new(right_type_result.is_incomplete.get()),
            ..TypeResult::new(right_type)
        }),
        node.0,
        inference_context,
        diag,
        &BinaryOperationOptions {
            is_literal_math_allowed: Some(is_literal_math_allowed),
            is_tuple_add_allowed: Some(is_tuple_add_allowed),
        },
    );

    if type_result.is_incomplete.get().unwrap_or(false) {
        is_incomplete = true;
    }

    if !diag.is_empty() {
        type_errors = true;

        if !is_incomplete {
            if is_left_optional_type && diag.get_messages().len() == 1 {
                // If the left was an optional type and there is just one diagnostic,
                // assume that it was due to a "None" not being supported. Report
                // this as a reportOptionalOperand diagnostic rather than a
                // reportGeneralTypeIssues diagnostic.
                evaluator.add_diagnostic(
                    DiagnosticRule::reportOptionalOperand,
                    &LocMessage::none_operator().format(&[("operator", print_operator(operator))]),
                    node.d().left_expr.get(),
                    None,
                );
            } else {
                // If neither the LHS or RHS are unions, don't include a diagnostic addendum
                // because it will be redundant with the main diagnostic message. The addenda
                // are useful only if union expansion was used for one or both operands.
                let mut diag_string = String::new();
                if is_union(evaluator.make_top_level_type_vars_concrete(left_type, false, None))
                    || is_union(
                        evaluator.make_top_level_type_vars_concrete(right_type, false, None),
                    )
                {
                    diag_string = diag.get_string(
                        DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                        DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                    );
                }

                let left_type_text = evaluator.print_type(left_type, None);
                let right_type_text = evaluator.print_type(right_type, None);
                evaluator.add_diagnostic(
                    DiagnosticRule::reportOperatorIssue,
                    &(LocMessage::type_not_support_binary_operator().format(&[
                        ("operator", print_operator(operator)),
                        ("leftType", &left_type_text),
                        ("rightType", &right_type_text),
                    ]) + &diag_string),
                    node.0,
                    None,
                );
            }
        }
    }

    P::new_eval(TypeResult {
        is_incomplete: Cell::new(Some(is_incomplete)),
        type_errors: Cell::new(Some(type_errors)),
        cold: TypeResultCold {
            magic_method_deprecation_info: type_result.cold().magic_method_deprecation_info.clone(),
            ..Default::default()
        }
        .into_cold(),
        ..TypeResult::new(type_result.type_.get())
    })
}

// analyzer/operations.ts:492
pub fn get_type_of_augmented_assignment(
    evaluator: &TypeEvaluator,
    node: AugmentedAssignmentNode,
    inference_context: Option<P<InferenceContext>>,
) -> P<TypeResult> {
    // The TS local `operatorMap`: the magic method and the binary operator of each augmented operator.
    fn operator_map(operator: OperatorType) -> (&'static str, OperatorType) {
        match operator {
            OperatorType::AddEqual => ("__iadd__", OperatorType::Add),
            OperatorType::SubtractEqual => ("__isub__", OperatorType::Subtract),
            OperatorType::MultiplyEqual => ("__imul__", OperatorType::Multiply),
            OperatorType::FloorDivideEqual => ("__ifloordiv__", OperatorType::FloorDivide),
            OperatorType::DivideEqual => ("__itruediv__", OperatorType::Divide),
            OperatorType::ModEqual => ("__imod__", OperatorType::Mod),
            OperatorType::PowerEqual => ("__ipow__", OperatorType::Power),
            OperatorType::MatrixMultiplyEqual => ("__imatmul__", OperatorType::MatrixMultiply),
            OperatorType::BitwiseAndEqual => ("__iand__", OperatorType::BitwiseAnd),
            OperatorType::BitwiseOrEqual => ("__ior__", OperatorType::BitwiseOr),
            OperatorType::BitwiseXorEqual => ("__ixor__", OperatorType::BitwiseXor),
            OperatorType::LeftShiftEqual => ("__ilshift__", OperatorType::LeftShift),
            OperatorType::RightShiftEqual => ("__irshift__", OperatorType::RightShift),
            _ => unreachable!("an augmented assignment has an augmented operator"),
        }
    }

    let operator = node.d().operator.get();
    let diag = DiagnosticAddendum::new();
    let mut deprecated_info: Option<MagicMethodDeprecationInfo> = None;

    let left_type_result =
        evaluator.get_type_of_expression(node.d().left_expr.get(), EvalFlags::None, None);
    let left_type = left_type_result.type_.get();

    let mut expected_operand_type: Option<P<Type>> = None;
    if operator == OperatorType::BitwiseOrEqual {
        // If this is a bitwise or ("|="), use the type of the left operand. This allows
        // us to support the case where a TypedDict is being updated with a dict expression.
        expected_operand_type = Some(left_type);
    }

    let right_type_result = evaluator.get_type_of_expression(
        node.d().right_expr.get(),
        /* flags */ EvalFlags::None,
        make_inference_context(expected_operand_type, None, None),
    );
    let right_type = right_type_result.type_.get();
    let is_incomplete = right_type_result.is_incomplete.get().unwrap_or(false)
        || left_type_result.is_incomplete.get().unwrap_or(false);

    let type_result = if is_never(left_type) || is_never(right_type) {
        P::new_eval(TypeResult {
            is_incomplete: Cell::new(Some(is_incomplete)),
            ..TypeResult::new(NeverType::create_never().0)
        })
    } else {
        let type_ = evaluator.map_subtypes_expand_type_vars(
            left_type,
            /* options */ None,
            &mut |left_subtype_expanded, left_subtype_unexpanded, _| {
                Some(evaluator.map_subtypes_expand_type_vars(
                    right_type,
                    Some(&MapSubtypesOptions {
                        condition_filter: get_type_condition(left_subtype_expanded),
                        ..Default::default()
                    }),
                    &mut |right_subtype_expanded, right_subtype_unexpanded, _| {
                        if is_any_or_unknown(left_subtype_unexpanded)
                            || is_any_or_unknown(right_subtype_unexpanded)
                        {
                            return Some(preserve_unknown(
                                left_subtype_unexpanded,
                                right_subtype_unexpanded,
                            ));
                        }

                        let magic_method_name = operator_map(operator).0;
                        let right_arg = |type_: P<Type>| {
                            P::new_eval(TypeResult {
                                is_incomplete: Cell::new(right_type_result.is_incomplete.get()),
                                ..TypeResult::new(type_)
                            })
                        };
                        let mut return_type_result = evaluator.get_type_of_magic_method_call(
                            left_subtype_unexpanded,
                            magic_method_name,
                            &[right_arg(right_subtype_unexpanded)],
                            node.0,
                            inference_context,
                            None,
                        );

                        if return_type_result.is_none()
                            && left_subtype_unexpanded != left_subtype_expanded
                        {
                            // Try with the expanded left type.
                            return_type_result = evaluator.get_type_of_magic_method_call(
                                left_subtype_expanded,
                                magic_method_name,
                                &[right_arg(right_subtype_unexpanded)],
                                node.0,
                                inference_context,
                                None,
                            );
                        }

                        if return_type_result.is_none()
                            && right_subtype_unexpanded != right_subtype_expanded
                        {
                            // Try with the expanded left and right type.
                            return_type_result = evaluator.get_type_of_magic_method_call(
                                left_subtype_expanded,
                                magic_method_name,
                                &[right_arg(right_subtype_expanded)],
                                node.0,
                                inference_context,
                                None,
                            );
                        }

                        if return_type_result.is_none() {
                            // If the LHS class didn't support the magic method for augmented
                            // assignment, fall back on the normal binary expression evaluator.
                            let binary_operator = operator_map(operator).1;

                            // Don't use literal math if the operation is within a loop
                            // because the literal values may change each time.
                            let is_literal_math_allowed = !is_within_loop(node.0)
                                && is_expression_local_variable(
                                    evaluator,
                                    node.d().left_expr.get(),
                                )
                                && get_union_subtype_count(left_type)
                                    * get_union_subtype_count(right_type)
                                    < MAX_LITERAL_MATH_SUBTYPE_COUNT;

                            // Don't special-case tuple __add__ if the left type is a union. This
                            // can result in an infinite loop if we keep creating new tuple types
                            // within a loop construct using __add__.
                            let is_tuple_add_allowed = !is_union(left_type);

                            return_type_result = Some(validate_binary_operation(
                                evaluator,
                                binary_operator,
                                P::new_eval(TypeResult {
                                    is_incomplete: Cell::new(left_type_result.is_incomplete.get()),
                                    ..TypeResult::new(left_subtype_unexpanded)
                                }),
                                right_arg(right_subtype_unexpanded),
                                node.0,
                                inference_context,
                                diag,
                                &BinaryOperationOptions {
                                    is_literal_math_allowed: Some(is_literal_math_allowed),
                                    is_tuple_add_allowed: Some(is_tuple_add_allowed),
                                },
                            ));
                        }

                        if let Some(info) = return_type_result
                            .and_then(|result| result.cold().magic_method_deprecation_info.clone())
                        {
                            deprecated_info = Some(info);
                        }

                        return_type_result.map(|result| result.type_.get())
                    },
                    0,
                ))
            },
            0,
        );

        // If the LHS class didn't support the magic method for augmented
        // assignment, fall back on the normal binary expression evaluator.
        if (!diag.is_empty() || is_never(type_)) && !is_incomplete {
            let left_type_text = evaluator.print_type(left_type, None);
            let right_type_text = evaluator.print_type(right_type, None);
            evaluator.add_diagnostic(
                DiagnosticRule::reportOperatorIssue,
                &(LocMessage::type_not_support_binary_operator().format(&[
                    ("operator", print_operator(operator)),
                    ("leftType", &left_type_text),
                    ("rightType", &right_type_text),
                ]) + &diag.get_string(
                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                )),
                node.0,
                None,
            );
        }

        P::new_eval(TypeResult {
            is_incomplete: Cell::new(Some(is_incomplete)),
            cold: TypeResultCold {
                magic_method_deprecation_info: deprecated_info,
                ..Default::default()
            }
            .into_cold(),
            ..TypeResult::new(type_)
        })
    };

    evaluator.assign_type_to_expression(
        node.d().dest_expr.get(),
        type_result,
        node.d().right_expr.get(),
        false,
        false,
        None,
    );

    type_result
}

// analyzer/operations.ts:646
pub fn get_type_of_unary_operation(
    evaluator: &TypeEvaluator,
    node: UnaryOperationNode,
    flags: EvalFlags,
    inference_context: Option<P<InferenceContext>>,
) -> P<TypeResult> {
    if flags.any(EvalFlags::TypeExpression) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportInvalidTypeForm,
            &LocMessage::unary_operation_not_allowed(),
            node.0,
            None,
        );
        return P::new_eval(TypeResult::new(UnknownType::create(false).0));
    }

    let operator = node.d().operator.get();
    let expr_type_result =
        evaluator.get_type_of_expression(node.d().expr.get(), EvalFlags::None, None);
    let mut expr_type = evaluator.make_top_level_type_vars_concrete(
        transform_possible_recursive_type_alias(Some(expr_type_result.type_.get()), 0).unwrap(),
        false,
        None,
    );

    let is_incomplete = expr_type_result.is_incomplete.get();

    if is_never(expr_type) {
        return P::new_eval(TypeResult {
            is_incomplete: Cell::new(is_incomplete),
            ..TypeResult::new(NeverType::create_never().0)
        });
    }

    // Map unary operators to magic functions. Note that the bitwise
    // invert has two magic functions that are aliases of each other.
    let unary_operator_map = |operator: OperatorType| -> &'static str {
        match operator {
            OperatorType::Add => "__pos__",
            OperatorType::Subtract => "__neg__",
            OperatorType::BitwiseInvert => "__invert__",
            OperatorType::Not => "__bool__",
            _ => unreachable!("a unary operation has a unary operator"),
        }
    };

    let mut type_: Option<P<Type>> = None;
    let mut deprecated_info: Option<MagicMethodDeprecationInfo> = None;

    if operator != OperatorType::Not && is_optional_type(expr_type) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportOptionalOperand,
            &LocMessage::none_operator().format(&[("operator", print_operator(operator))]),
            node.d().expr.get(),
            None,
        );
        expr_type = remove_none_from_union(expr_type);
    }

    // Handle certain operations on certain literal types
    // using special-case math. Do not apply this if the input type
    // is incomplete because we may be evaluating an expression within
    // a loop, so the literal value may change each time.
    if !expr_type_result.is_incomplete.get().unwrap_or(false) {
        type_ = calc_literal_for_unary_op(operator, expr_type);
    }

    if type_.is_none() {
        if is_any_or_unknown(expr_type) {
            type_ = Some(expr_type);
        } else {
            let magic_method_name = unary_operator_map(operator);
            let mut is_result_valid = true;

            type_ = Some(evaluator.map_subtypes_expand_type_vars(
                expr_type,
                /* options */ None,
                &mut |subtype_expanded, _, _| {
                    let type_result = evaluator.get_type_of_magic_method_call(
                        subtype_expanded,
                        magic_method_name,
                        &[],
                        node.0,
                        inference_context,
                        None,
                    );

                    if type_result.is_none() {
                        is_result_valid = false;
                    }

                    if let Some(info) =
                        type_result.and_then(|result| result.cold().magic_method_deprecation_info.clone())
                    {
                        deprecated_info = Some(info);
                    }

                    type_result.map(|result| result.type_.get())
                },
                0,
            ));

            if !is_result_valid {
                type_ = None;
            }
        }

        // __not__ always returns a boolean.
        if operator == OperatorType::Not {
            // `getBuiltInObject` always returns a type, so the TS `if (!type)` fallback never runs.
            type_ = Some(evaluator.get_built_in_object(node.0, "bool", None));
        }

        if type_.is_none() {
            if !is_incomplete.unwrap_or(false) {
                let expr_type_text = evaluator.print_type(expr_type, None);
                match inference_context.filter(|inference_context| {
                    !is_any_or_unknown(inference_context.expected_type.get())
                }) {
                    Some(inference_context) => {
                        let expected_type_text =
                            evaluator.print_type(inference_context.expected_type.get(), None);
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportOperatorIssue,
                            &LocMessage::type_not_support_unary_operator_bidirectional().format(&[
                                ("operator", print_operator(operator)),
                                ("type", &expr_type_text),
                                ("expectedType", &expected_type_text),
                            ]),
                            node.0,
                            None,
                        );
                    }
                    None => {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportOperatorIssue,
                            &LocMessage::type_not_support_unary_operator().format(&[
                                ("operator", print_operator(operator)),
                                ("type", &expr_type_text),
                            ]),
                            node.0,
                            None,
                        );
                    }
                }
            }

            type_ = Some(UnknownType::create(is_incomplete.unwrap_or(false)).0);
        }
    }

    P::new_eval(TypeResult {
        is_incomplete: Cell::new(is_incomplete),
        cold: TypeResultCold {
            magic_method_deprecation_info: deprecated_info,
            ..Default::default()
        }
        .into_cold(),
        ..TypeResult::new(type_.unwrap())
    })
}

// analyzer/operations.ts:770
pub fn get_type_of_ternary_operation(
    evaluator: &TypeEvaluator,
    node: TernaryNode,
    flags: EvalFlags,
    inference_context: Option<P<InferenceContext>>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<TypeResult> {
    let file_info = node_info.get_file_info(node.0);

    if flags.any(EvalFlags::TypeExpression) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportInvalidTypeForm,
            &LocMessage::ternary_not_allowed(),
            node.0,
            None,
        );
        return P::new_eval(TypeResult::new(UnknownType::create(false).0));
    }

    evaluator.get_type_of_expression(node.d().test_expr.get(), EvalFlags::None, None);

    let mut types_to_combine: Vec<P<Type>> = Vec::new();
    let mut is_incomplete = false;
    let mut type_errors = false;

    let const_expr_value = evaluate_static_bool_expression(
        node.d().test_expr.get(),
        &file_info.execution_environment,
        &file_info.defined_constants,
        None,
        None,
    );

    if const_expr_value != Some(false) && evaluator.is_node_reachable(node.d().if_expr.get(), None)
    {
        let if_type =
            evaluator.get_type_of_expression(node.d().if_expr.get(), flags, inference_context);
        types_to_combine.push(if_type.type_.get());
        if if_type.is_incomplete.get().unwrap_or(false) {
            is_incomplete = true;
        }
        if if_type.type_errors.get().unwrap_or(false) {
            type_errors = true;
        }
    }

    if const_expr_value != Some(true) && evaluator.is_node_reachable(node.d().else_expr.get(), None)
    {
        let else_type =
            evaluator.get_type_of_expression(node.d().else_expr.get(), flags, inference_context);
        types_to_combine.push(else_type.type_.get());
        if else_type.is_incomplete.get().unwrap_or(false) {
            is_incomplete = true;
        }
        if else_type.type_errors.get().unwrap_or(false) {
            type_errors = true;
        }
    }

    P::new_eval(TypeResult {
        is_incomplete: Cell::new(Some(is_incomplete)),
        type_errors: Cell::new(Some(type_errors)),
        ..TypeResult::new(combine_types(&types_to_combine, None))
    })
}

// analyzer/operations.ts:821
pub(crate) fn create_union_type(
    evaluator: &TypeEvaluator,
    node: BinaryOperationNode,
    flags: EvalFlags,
    left_type_result: P<TypeResult>,
    right_type_result: P<TypeResult>,
    adjusted_right_type: P<Type>,
    adjusted_left_type: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<TypeResult> {
    let left_expression = node.d().left_expr.get();
    let right_expression = node.d().right_expr.get();
    let file_info = node_info.get_file_info(node.0);
    let union_notation_supported = file_info.is_stub_file
        || flags.any(EvalFlags::ForwardRefs)
        || PythonVersion::is_greater_or_equal_to(
            &file_info.execution_environment.python_version,
            &PYTHON_VERSION3_10,
        );

    if !union_notation_supported {
        // If the left type is Any, we can't say for sure whether this
        // is an illegal syntax or a valid application of the "|" operator.
        if !is_any_or_unknown(adjusted_left_type) {
            let operator_token = node.d().operator_token.get();
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::union_syntax_illegal(),
                node.0,
                Some(&TextRange {
                    start: operator_token.start,
                    length: operator_token.length,
                }),
            );
        }
    }

    let is_left_type_arg_valid = evaluator.validate_type_arg(
        &TypeResultWithNode::from_type_result(&left_type_result, left_expression),
        None,
    );
    let is_right_type_arg_valid = evaluator.validate_type_arg(
        &TypeResultWithNode::from_type_result(&right_type_result, right_expression),
        None,
    );

    if !is_left_type_arg_valid || !is_right_type_arg_valid {
        return P::new_eval(TypeResult::new(UnknownType::create(false).0));
    }

    let adjusted_left_type = evaluator.report_missing_type_args(
        node.d().left_expr.get(),
        adjusted_left_type,
        flags | EvalFlags::InstantiableType,
    );
    let adjusted_right_type = evaluator.report_missing_type_args(
        node.d().right_expr.get(),
        adjusted_right_type,
        flags | EvalFlags::InstantiableType,
    );

    let mut new_union = combine_types(
        &[adjusted_left_type, adjusted_right_type],
        Some(&CombineTypesOptions {
            skip_elide_redundant_literals: Some(true),
            ..Default::default()
        }),
    );

    let union_class = evaluator.get_union_class_type();
    if is_instantiable_class(union_class) && !flags.any(EvalFlags::IsinstanceArg) {
        new_union = TypeBase::clone_as_special_form(
            new_union,
            Some(ClassType::clone_as_instance(ClassType(union_class), true)),
        );
    }

    let type_form_of = |type_: P<Type>| {
        type_
            .props
            .borrow()
            .as_ref()
            .and_then(|props| props.type_form)
    };
    if let (Some(left_type_form), Some(right_type_form)) = (
        type_form_of(left_type_result.type_.get()),
        type_form_of(right_type_result.type_.get()),
    ) {
        let new_type_form = combine_types(&[left_type_form, right_type_form], None);
        new_union = TypeBase::clone_with_type_form(new_union, Some(new_type_form));
    }

    // Check for "stringified" forward reference type expressions. The "|" operator
    // doesn't support these except in certain circumstances. Notably, it can't be used
    // with other strings or with types that are not specialized using an index form.
    if !file_info.is_stub_file {
        let mut string_and_other: Option<(ExpressionNode, P<Type>)> = None;

        if left_expression.node_type == ParseNodeType::StringList {
            string_and_other = Some((left_expression, right_type_result.type_.get()));
        } else if right_expression.node_type == ParseNodeType::StringList {
            string_and_other = Some((right_expression, left_type_result.type_.get()));
        }

        if let Some((string_node, other_type)) = string_and_other {
            let mut is_allowed = true;
            if is_class(other_type)
                && (!ClassType(other_type)
                    .d()
                    .priv_
                    .borrow()
                    .is_type_arg_explicit
                    .unwrap_or(false)
                    || is_class_instance(other_type))
            {
                is_allowed = false;
            }

            if !is_allowed {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportGeneralTypeIssues,
                    &LocMessage::union_forward_reference_not_allowed(),
                    string_node,
                    None,
                );
            }
        }
    }

    P::new_eval(TypeResult::new(new_union))
}

// analyzer/operations.ts:922
pub(crate) fn calc_literal_for_unary_op(
    operator: OperatorType,
    operand_type: P<Type>,
) -> Option<P<Type>> {
    // `Number.MIN_SAFE_INTEGER` and `Number.MAX_SAFE_INTEGER`.
    const MIN_SAFE_INTEGER: f64 = -9007199254740991.0;
    const MAX_SAFE_INTEGER: f64 = 9007199254740991.0;

    if get_union_subtype_count(operand_type) >= MAX_LITERAL_MATH_SUBTYPE_COUNT {
        return None;
    }

    if get_type_condition(operand_type).is_some()
        || some_subtypes(operand_type, &mut |subtype| {
            get_type_condition(subtype).is_some()
        })
    {
        return None;
    }

    let literal_class_name = get_literal_type_class_name(operand_type);
    let literal_value_of =
        |subtype: P<Type>| ClassType(subtype).d().priv_.borrow().literal_value.clone();

    let mut type_: Option<P<Type>> = None;
    if literal_class_name.as_deref() == Some("int") {
        if operator == OperatorType::Add {
            type_ = Some(operand_type);
        } else if operator == OperatorType::Subtract {
            type_ = Some(map_subtypes(
                operand_type,
                &mut |subtype| {
                    let negated = match literal_value_of(subtype) {
                        Some(LiteralValue::Number(value)) => LiteralValue::Number(-value),
                        Some(LiteralValue::Bigint(value)) => LiteralValue::Bigint(-value),
                        _ => unreachable!("an int literal holds a number or a bigint"),
                    };
                    Some(ClassType::clone_with_literal(ClassType(subtype), Some(negated)).0)
                },
                None,
            ));
        } else if operator == OperatorType::BitwiseInvert {
            // Python defines bitwise invert (~x) as -(x + 1). Use BigInt math
            // to avoid JavaScript's 32-bit truncation when using the ~ operator
            // on Number values.
            type_ = Some(map_subtypes(
                operand_type,
                &mut |subtype| {
                    let big_val = match literal_value_of(subtype) {
                        Some(LiteralValue::Bigint(value)) => value,
                        Some(LiteralValue::Number(value)) => {
                            JsBigInt::from_f64(value).expect("BigInt(n) of an int literal value")
                        }
                        _ => unreachable!("an int literal holds a number or a bigint"),
                    };
                    let new_value = -big_val
                        .checked_add(&JsBigInt::from(1))
                        .expect("an int literal plus one fits a bigint");
                    let new_value =
                        if new_value >= MIN_SAFE_INTEGER && new_value <= MAX_SAFE_INTEGER {
                            LiteralValue::Number(new_value.to_f64())
                        } else {
                            LiteralValue::Bigint(new_value)
                        };
                    Some(ClassType::clone_with_literal(ClassType(subtype), Some(new_value)).0)
                },
                None,
            ));
        }
    } else if literal_class_name.as_deref() == Some("bool") && operator == OperatorType::Not {
        type_ = Some(map_subtypes(
            operand_type,
            &mut |subtype| {
                let Some(LiteralValue::Boolean(value)) = literal_value_of(subtype) else {
                    unreachable!("a bool literal holds a boolean");
                };
                Some(
                    ClassType::clone_with_literal(
                        ClassType(subtype),
                        Some(LiteralValue::Boolean(!value)),
                    )
                    .0,
                )
            },
            None,
        ));
    }

    type_
}

// analyzer/operations.ts:971
pub(crate) fn calc_literal_for_binary_op(
    operator: OperatorType,
    left_type: P<Type>,
    right_type: P<Type>,
) -> Option<P<Type>> {
    // `Number.MIN_SAFE_INTEGER` and `Number.MAX_SAFE_INTEGER`.
    const MIN_SAFE_INTEGER: f64 = -9007199254740991.0;
    const MAX_SAFE_INTEGER: f64 = 9007199254740991.0;

    let left_literal_class_name = get_literal_type_class_name(left_type);
    let left_literal_class_name = left_literal_class_name?;
    if get_type_condition(left_type).is_some()
        || some_subtypes(left_type, &mut |subtype| {
            get_type_condition(subtype).is_some()
        })
    {
        return None;
    }

    let right_literal_class_name = get_literal_type_class_name(right_type);
    if right_literal_class_name.as_deref() != Some(left_literal_class_name.as_str())
        || get_type_condition(right_type).is_some()
        || some_subtypes(right_type, &mut |subtype| {
            get_type_condition(subtype).is_some()
        })
        || get_union_subtype_count(left_type) * get_union_subtype_count(right_type)
            >= MAX_LITERAL_MATH_SUBTYPE_COUNT
    {
        return None;
    }

    let literal_value_of =
        |subtype: P<Type>| ClassType(subtype).d().priv_.borrow().literal_value.clone();

    // Handle str and bytes literals.
    if (left_literal_class_name == "str" || left_literal_class_name == "bytes")
        && operator == OperatorType::Add
    {
        return Some(map_subtypes(
            left_type,
            &mut |left_subtype| {
                Some(map_subtypes(
                    right_type,
                    &mut |right_subtype| {
                        let (
                            Some(LiteralValue::String(left_value)),
                            Some(LiteralValue::String(right_value)),
                        ) = (
                            literal_value_of(left_subtype),
                            literal_value_of(right_subtype),
                        )
                        else {
                            unreachable!("str and bytes literals hold strings");
                        };

                        Some(
                            ClassType::clone_with_literal(
                                ClassType(left_subtype),
                                Some(LiteralValue::String(left_value + &right_value)),
                            )
                            .0,
                        )
                    },
                    None,
                ))
            },
            None,
        ));
    }

    // Handle int literals.
    if left_literal_class_name == "int" {
        let supported_ops = [
            OperatorType::Add,
            OperatorType::Subtract,
            OperatorType::Multiply,
            OperatorType::FloorDivide,
            OperatorType::Mod,
            OperatorType::Power,
            OperatorType::LeftShift,
            OperatorType::RightShift,
            OperatorType::BitwiseAnd,
            OperatorType::BitwiseOr,
            OperatorType::BitwiseXor,
        ];
        if !supported_ops.contains(&operator) {
            return None;
        }

        let mut is_valid_result = true;

        // `BigInt(value)` of an int literal value; `None` where JS throws.
        let to_bigint = |value: Option<LiteralValue>| -> Option<JsBigInt> {
            match value {
                Some(LiteralValue::Bigint(value)) => Some(value),
                Some(LiteralValue::Number(value)) => JsBigInt::from_f64(value),
                _ => unreachable!("an int literal holds a number or a bigint"),
            }
        };

        let type_ = map_subtypes(
            left_type,
            &mut |left_subtype| {
                Some(map_subtypes(
                    right_type,
                    &mut |right_subtype| {
                        // The TS `try` block: every `None` below is a value that is undefined
                        // or a bigint operation that throws, and both end the same way.
                        let left_literal_value = to_bigint(literal_value_of(left_subtype));
                        let right_literal_value = to_bigint(literal_value_of(right_subtype));
                        let new_value: Option<JsBigInt> =
                            match (left_literal_value, right_literal_value) {
                                (Some(left_literal_value), Some(right_literal_value)) => {
                                    match operator {
                                        OperatorType::Add => {
                                            left_literal_value.checked_add(&right_literal_value)
                                        }
                                        OperatorType::Subtract => {
                                            left_literal_value.checked_sub(&right_literal_value)
                                        }
                                        OperatorType::Multiply => {
                                            left_literal_value.checked_mul(&right_literal_value)
                                        }
                                        OperatorType::FloorDivide => {
                                            if !right_literal_value.is_zero() {
                                                let quotient = left_literal_value
                                                    .checked_div(&right_literal_value);

                                                // BigInt rounds to zero, but floor divide rounds to negative
                                                // infinity, so we need to adjust the result if the signs
                                                // of the operands are different.
                                                quotient.and_then(|quotient| {
                                                    let product = quotient
                                                        .checked_mul(&right_literal_value)?;
                                                    if product != left_literal_value
                                                        && left_literal_value.is_negative()
                                                            != right_literal_value.is_negative()
                                                    {
                                                        quotient.checked_sub(&JsBigInt::from(1))
                                                    } else {
                                                        Some(quotient)
                                                    }
                                                })
                                            } else {
                                                None
                                            }
                                        }
                                        OperatorType::Mod => {
                                            if !right_literal_value.is_zero() {
                                                // BigInt always produces a remainder, but Python produces
                                                // a modulo result whose sign is always the same as the
                                                // right operand.
                                                left_literal_value
                                                    .checked_rem(&right_literal_value)
                                                    .and_then(|rem| {
                                                        rem.checked_add(&right_literal_value)
                                                    })
                                                    .and_then(|sum| {
                                                        sum.checked_rem(&right_literal_value)
                                                    })
                                            } else {
                                                None
                                            }
                                        }
                                        OperatorType::Power => {
                                            if !right_literal_value.is_negative() {
                                                // Don't allow if we exceed max bigint integer value.
                                                left_literal_value.checked_pow(&right_literal_value)
                                            } else {
                                                None
                                            }
                                        }
                                        OperatorType::LeftShift => {
                                            if !right_literal_value.is_negative() {
                                                left_literal_value.checked_shl(&right_literal_value)
                                            } else {
                                                None
                                            }
                                        }
                                        OperatorType::RightShift => {
                                            if !right_literal_value.is_negative() {
                                                left_literal_value.checked_shr(&right_literal_value)
                                            } else {
                                                None
                                            }
                                        }
                                        OperatorType::BitwiseAnd => {
                                            Some(&left_literal_value & &right_literal_value)
                                        }
                                        OperatorType::BitwiseOr => {
                                            Some(&left_literal_value | &right_literal_value)
                                        }
                                        OperatorType::BitwiseXor => {
                                            Some(&left_literal_value ^ &right_literal_value)
                                        }
                                        _ => None,
                                    }
                                }
                                _ => None,
                            };

                        let Some(new_value) = new_value else {
                            is_valid_result = false;
                            return None;
                        };

                        // Convert back to a simple number if it fits. Leave as a bigint
                        // if it doesn't.
                        let new_value =
                            if new_value >= MIN_SAFE_INTEGER && new_value <= MAX_SAFE_INTEGER {
                                LiteralValue::Number(new_value.to_f64())
                            } else {
                                LiteralValue::Bigint(new_value)
                            };

                        Some(
                            ClassType::clone_with_literal(ClassType(left_subtype), Some(new_value))
                                .0,
                        )
                    },
                    None,
                ))
            },
            None,
        );

        if is_valid_result {
            return Some(type_);
        }
    }

    None
}

// analyzer/operations.ts:1119
pub(crate) fn custom_metaclass_supports_method(type_: P<Type>, method_name: &str) -> bool {
    if !is_instantiable_class(type_) {
        return false;
    }

    let metaclass = ClassType(type_).d().shared.get().effective_metaclass.get();
    let Some(metaclass) = metaclass.filter(|&metaclass| is_instantiable_class(metaclass)) else {
        return false;
    };

    if ClassType::is_built_in(ClassType(metaclass), Some(&["type".to_string()])) {
        return false;
    }

    let Some(member_info) = look_up_class_member(
        ClassType(metaclass),
        method_name,
        MemberAccessFlags::Default,
        None,
    ) else {
        return false;
    };

    // If the metaclass inherits from Any or Unknown, we have to guess
    // whether the method is supported. We'll assume it's not, since this
    // is the most likely case.
    if is_any_or_unknown(member_info.class_type) {
        return false;
    }

    if is_instantiable_class(member_info.class_type)
        && ClassType::is_built_in(
            ClassType(member_info.class_type),
            Some(&["type".to_string()]),
        )
    {
        return false;
    }

    true
}

// analyzer/operations.ts:1155
pub(crate) fn convert_function_to_object(evaluator: &TypeEvaluator, type_: P<Type>) -> P<Type> {
    if is_function_or_overloaded(type_) {
        return evaluator.get_object_type();
    }

    type_
}

// analyzer/operations.ts:1165
pub(crate) fn is_expression_local_variable(
    evaluator: &TypeEvaluator,
    node: ExpressionNode,
) -> bool {
    let Some(name_node) = NameNode::cast(node) else {
        return false;
    };

    let symbol_with_scope = evaluator.look_up_symbol_recursive(
        node,
        &name_node.d().value,
        /* honorCodeFlow */ false,
        false,
    );
    let Some(symbol_with_scope) = symbol_with_scope else {
        return false;
    };

    let current_scope = get_scope_for_node(node, evaluator.get_analyzer_node_info_reader().get());
    current_scope == Some(symbol_with_scope.scope)
}

// analyzer/operations.ts:1179
pub(crate) fn validate_containment_operation(
    evaluator: &TypeEvaluator,
    operator: OperatorType,
    left_type_result: P<TypeResult>,
    concrete_left_type: P<Type>,
    right_type_result: P<TypeResult>,
    error_node: ExpressionNode,
    diag: P<DiagnosticAddendum>,
) -> P<TypeResult> {
    let mut deprecated_info: Option<MagicMethodDeprecationInfo> = None;

    let type_ = evaluator.map_subtypes_expand_type_vars(
        right_type_result.type_.get(),
        /* options */ None,
        &mut |right_subtype_expanded, right_subtype_unexpanded, _| {
            Some(evaluator.map_subtypes_expand_type_vars(
                concrete_left_type,
                Some(&MapSubtypesOptions {
                    condition_filter: get_type_condition(right_subtype_expanded),
                    ..Default::default()
                }),
                &mut |left_subtype, _, _| {
                    if is_any_or_unknown(left_subtype)
                        || is_any_or_unknown(right_subtype_unexpanded)
                    {
                        return Some(preserve_unknown(left_subtype, right_subtype_expanded));
                    }

                    let mut return_type_result = evaluator.get_type_of_magic_method_call(
                        right_subtype_expanded,
                        "__contains__",
                        &[P::new_eval(TypeResult {
                            is_incomplete: Cell::new(left_type_result.is_incomplete.get()),
                            ..TypeResult::new(left_subtype)
                        })],
                        error_node,
                        /* inferenceContext */ None,
                        None,
                    );

                    if return_type_result.is_none() {
                        // If __contains__ was not supported, fall back
                        // on an iterable.
                        let iterator_type = evaluator
                            .get_type_of_iterator(
                                P::new_eval(TypeResult {
                                    is_incomplete: Cell::new(right_type_result.is_incomplete.get()),
                                    ..TypeResult::new(right_subtype_expanded)
                                }),
                                /* isAsync */ false,
                                error_node,
                                /* emitNotIterableError */ false,
                            )
                            .map(|result| result.type_.get());

                        if let Some(iterator_type) = iterator_type {
                            if evaluator.assign_type(
                                iterator_type,
                                left_subtype,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                return_type_result = Some(P::new_eval(TypeResult::new(
                                    evaluator.get_built_in_object(error_node, "bool", None),
                                )));
                            }
                        }
                    }

                    if return_type_result.is_none() {
                        let left_type_text = evaluator.print_type(left_subtype, None);
                        let right_type_text = evaluator.print_type(right_subtype_expanded, None);
                        diag.add_message(LocMessage::type_not_support_binary_operator().format(&[
                            ("operator", print_operator(operator)),
                            ("leftType", &left_type_text),
                            ("rightType", &right_type_text),
                        ]));
                    }

                    if let Some(info) = return_type_result
                        .and_then(|result| result.cold().magic_method_deprecation_info.clone())
                    {
                        deprecated_info = Some(info);
                    }

                    Some(match return_type_result {
                        Some(result) => result.type_.get(),
                        None => evaluator.get_built_in_object(error_node, "bool", None),
                    })
                },
                0,
            ))
        },
        0,
    );

    P::new_eval(TypeResult {
        cold: TypeResultCold {
            magic_method_deprecation_info: deprecated_info,
            ..Default::default()
        }
        .into_cold(),
        ..TypeResult::new(type_)
    })
}

// analyzer/operations.ts:1248
pub(crate) fn validate_arithmetic_operation(
    evaluator: &TypeEvaluator,
    operator: OperatorType,
    left_type_result: P<TypeResult>,
    right_type_result: P<TypeResult>,
    error_node: ExpressionNode,
    inference_context: Option<P<InferenceContext>>,
    diag: P<DiagnosticAddendum>,
    options: &BinaryOperationOptions,
) -> P<TypeResult> {
    let mut deprecated_info: Option<MagicMethodDeprecationInfo> = None;
    let is_incomplete = left_type_result.is_incomplete.get().unwrap_or(false)
        || right_type_result.is_incomplete.get().unwrap_or(false);
    let (magic_method_name, alt_magic_method_name) = BINARY_OPERATOR_MAP
        .with(|map| map.get(&operator).cloned())
        .expect("an arithmetic operator has magic methods");

    let type_ = evaluator.map_subtypes_expand_type_vars(
        left_type_result.type_.get(),
        /* options */ None,
        &mut |left_subtype_expanded, left_subtype_unexpanded, _| {
            Some(evaluator.map_subtypes_expand_type_vars(
                right_type_result.type_.get(),
                Some(&MapSubtypesOptions {
                    condition_filter: get_type_condition(left_subtype_expanded),
                    ..Default::default()
                }),
                &mut |right_subtype_expanded, right_subtype_unexpanded, _| {
                    if is_any_or_unknown(left_subtype_unexpanded)
                        || is_any_or_unknown(right_subtype_unexpanded)
                    {
                        return Some(preserve_unknown(
                            left_subtype_unexpanded,
                            right_subtype_unexpanded,
                        ));
                    }

                    let tuple_class_type = evaluator.get_tuple_class_type();

                    // Special-case __add__ for tuples when the types for both tuples are known.
                    if options.is_tuple_add_allowed.unwrap_or(false)
                        && operator == OperatorType::Add
                        && is_class_instance(left_subtype_expanded)
                        && is_tuple_class(ClassType(left_subtype_expanded))
                        && is_class_instance(right_subtype_expanded)
                        && is_tuple_class(ClassType(right_subtype_expanded))
                    {
                        let left_tuple_type_args = ClassType(left_subtype_expanded)
                            .d()
                            .priv_
                            .borrow()
                            .tuple_type_args
                            .map(|tuple_type_args| tuple_type_args.borrow().clone());
                        let right_tuple_type_args = ClassType(right_subtype_expanded)
                            .d()
                            .priv_
                            .borrow()
                            .tuple_type_args
                            .map(|tuple_type_args| tuple_type_args.borrow().clone());
                        if let (
                            Some(left_tuple_type_args),
                            Some(right_tuple_type_args),
                            Some(tuple_class_type),
                        ) = (
                            left_tuple_type_args,
                            right_tuple_type_args,
                            tuple_class_type,
                        ) {
                            // If at least one of the tuples is of fixed size, we can
                            // combine them into a precise new type. If both are unbounded
                            // (or contain an unbounded element), we cannot combine them
                            // in this manner because tuples can contain at most one
                            // unbounded element.
                            if is_instantiable_class(tuple_class_type.0)
                                && (!is_unbounded_tuple_class(ClassType(left_subtype_expanded))
                                    .unwrap_or(false)
                                    || !is_unbounded_tuple_class(ClassType(right_subtype_expanded))
                                        .unwrap_or(false))
                            {
                                let mut tuple_type_args = left_tuple_type_args;
                                tuple_type_args.extend(right_tuple_type_args);
                                return Some(
                                    ClassType::clone_as_instance(
                                        specialize_tuple_class(
                                            tuple_class_type,
                                            &tuple_type_args,
                                            true,
                                            false,
                                        ),
                                        true,
                                    )
                                    .0,
                                );
                            }
                        }
                    }

                    let left_arg = |type_: P<Type>| {
                        P::new_eval(TypeResult {
                            is_incomplete: Cell::new(left_type_result.is_incomplete.get()),
                            ..TypeResult::new(type_)
                        })
                    };
                    let right_arg = |type_: P<Type>| {
                        P::new_eval(TypeResult {
                            is_incomplete: Cell::new(right_type_result.is_incomplete.get()),
                            ..TypeResult::new(type_)
                        })
                    };

                    let mut result_type_result = evaluator.get_type_of_magic_method_call(
                        convert_function_to_object(evaluator, left_subtype_unexpanded),
                        &magic_method_name,
                        &[right_arg(right_subtype_unexpanded)],
                        error_node,
                        inference_context,
                        None,
                    );

                    if result_type_result.is_none()
                        && left_subtype_unexpanded != left_subtype_expanded
                    {
                        // Try the expanded left type.
                        result_type_result = evaluator.get_type_of_magic_method_call(
                            convert_function_to_object(evaluator, left_subtype_expanded),
                            &magic_method_name,
                            &[right_arg(right_subtype_unexpanded)],
                            error_node,
                            inference_context,
                            None,
                        );
                    }

                    if result_type_result.is_none()
                        && right_subtype_unexpanded != right_subtype_expanded
                    {
                        // Try the expanded left and right type.
                        result_type_result = evaluator.get_type_of_magic_method_call(
                            convert_function_to_object(evaluator, left_subtype_expanded),
                            &magic_method_name,
                            &[right_arg(right_subtype_expanded)],
                            error_node,
                            inference_context,
                            None,
                        );
                    }

                    if result_type_result.is_none() {
                        // Try the alternate form (swapping right and left).
                        result_type_result = evaluator.get_type_of_magic_method_call(
                            convert_function_to_object(evaluator, right_subtype_unexpanded),
                            &alt_magic_method_name,
                            &[left_arg(left_subtype_unexpanded)],
                            error_node,
                            inference_context,
                            None,
                        );

                        if result_type_result.is_none()
                            && right_subtype_unexpanded != right_subtype_expanded
                        {
                            // Try the expanded right type.
                            result_type_result = evaluator.get_type_of_magic_method_call(
                                convert_function_to_object(evaluator, right_subtype_expanded),
                                &alt_magic_method_name,
                                &[left_arg(left_subtype_unexpanded)],
                                error_node,
                                inference_context,
                                None,
                            );
                        }

                        if result_type_result.is_none()
                            && left_subtype_unexpanded != left_subtype_expanded
                        {
                            // Try the expanded right and left type.
                            result_type_result = evaluator.get_type_of_magic_method_call(
                                convert_function_to_object(evaluator, right_subtype_expanded),
                                &alt_magic_method_name,
                                &[left_arg(left_subtype_expanded)],
                                error_node,
                                inference_context,
                                None,
                            );
                        }
                    }

                    if result_type_result.is_none() {
                        let left_type_text = evaluator.print_type(left_subtype_expanded, None);
                        let right_type_text = evaluator.print_type(right_subtype_expanded, None);
                        match inference_context.filter(|inference_context| {
                            !is_any_or_unknown(inference_context.expected_type.get())
                        }) {
                            Some(inference_context) => {
                                let expected_type_text = evaluator
                                    .print_type(inference_context.expected_type.get(), None);
                                diag.add_message(
                                    LocMessage::type_not_support_binary_operator_bidirectional()
                                        .format(&[
                                            ("operator", print_operator(operator)),
                                            ("leftType", &left_type_text),
                                            ("rightType", &right_type_text),
                                            ("expectedType", &expected_type_text),
                                        ]),
                                );
                            }
                            None => {
                                diag.add_message(
                                    LocMessage::type_not_support_binary_operator().format(&[
                                        ("operator", print_operator(operator)),
                                        ("leftType", &left_type_text),
                                        ("rightType", &right_type_text),
                                    ]),
                                );
                            }
                        }
                    }

                    if let Some(info) = result_type_result
                        .and_then(|result| result.cold().magic_method_deprecation_info.clone())
                    {
                        deprecated_info = Some(info);
                    }

                    Some(match result_type_result {
                        Some(result) => result.type_.get(),
                        None => UnknownType::create(is_incomplete).0,
                    })
                },
                0,
            ))
        },
        0,
    );

    P::new_eval(TypeResult {
        cold: TypeResultCold {
            magic_method_deprecation_info: deprecated_info,
            ..Default::default()
        }
        .into_cold(),
        ..TypeResult::new(type_)
    })
}
